import{H as e,V as t,et as n,j as r}from"./chunks/framework.Dj60FFN6.js";var i=JSON.parse(`{"title":"Funzione inversa","description":"","frontmatter":{},"headers":[],"relativePath":"lezioni/c_analisi/cc/cce.md","filePath":"lezioni/c_analisi/cc/cce.md"}`),a={name:`lezioni/c_analisi/cc/cce.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="funzione-inversa" tabindex="-1">Funzione inversa <a class="header-anchor" href="#funzione-inversa" aria-label="Permalink to “Funzione inversa”">​</a></h1><p>Una funzione è il legame che esiste fra un dominio ed un codominio; sotto certe condizioni è possibile ipotizzare un legame che faccia passare dal codominio al dominio: se questo è possibile tale funzione si chiama funzione inversa.</p><blockquote><p>Perché una funzione sia invertibile deve essere iniettiva e suriettiva, oppure puoi anche dire, in modo equivalente, deve essere continua e monotona.</p></blockquote><p>Controlla i seguenti link alla teoria degli insiemi:</p><ul><li><a href="./../../j/jd/jdd.html">applicazione iniettiva</a></li><li><a href="./../../j/jd/jde.html">applicazione suriettiva</a></li><li><a href="./../../j/jd/jdi.html">applicazione inversa</a></li></ul><p>Vediamo alcuni semplici esempi come da una funzione si possa passare alla sua funzione inversa.</p><p>Graficamente da una funzione si può ottenere il <a href="./../ci/ciae.html">grafico della funzione inversa</a> semplicemente operando un ribaltamento del piano cartesiano attorno alla bisettrice del primo e terzo quadrante: infatti essendo tale bisettrice di equazione <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>y</mi><mo>=</mo><mi>x</mi></mrow><annotation encoding="application/x-tex">y=x</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">y</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.4306em;"></span><span class="mord mathnormal">x</span></span></span></span> la bisettrice è la linea (funzione) che <a href="./cceba.html">scambia</a> fra loro le <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>x</mi></mrow><annotation encoding="application/x-tex">x</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.4306em;"></span><span class="mord mathnormal">x</span></span></span></span> e le <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>y</mi></mrow><annotation encoding="application/x-tex">y</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">y</span></span></span></span> (funzione identica).</p>`,7)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};